import{_ as a,H as n,f as t,i as l}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"17 | 模型解剖：探究模型内部到底是什么？","description":"","frontmatter":{},"headers":[{"level":2,"title":"模型文件","slug":"模型文件","link":"#模型文件","children":[]},{"level":2,"title":"权重和偏置","slug":"权重和偏置","link":"#权重和偏置","children":[]},{"level":2,"title":"y = kx + b","slug":"y-kx-b","link":"#y-kx-b","children":[]},{"level":2,"title":"k","slug":"k","link":"#k","children":[]},{"level":2,"title":"b","slug":"b","link":"#b","children":[]},{"level":2,"title":"k","slug":"k-1","link":"#k-1","children":[]},{"level":2,"title":"b","slug":"b-1","link":"#b-1","children":[]},{"level":2,"title":"模型可视化","slug":"模型可视化","link":"#模型可视化","children":[{"level":3,"title":"Embedding 层","slug":"embedding-层","link":"#embedding-层","children":[]},{"level":3,"title":"TransformerDecoderLayer","slug":"transformerdecoderlayer","link":"#transformerdecoderlayer","children":[]}]},{"level":2,"title":"y = kx + b","slug":"y-kx-b-1","link":"#y-kx-b-1","children":[]},{"level":2,"title":"a =","slug":"a","link":"#a","children":[]},{"level":2,"title":"ReLU(y)","slug":"relu-y","link":"#relu-y","children":[]},{"level":2,"title":"a","slug":"a-1","link":"#a-1","children":[]},{"level":2,"title":"x","slug":"x","link":"#x","children":[]},{"level":2,"title":"k","slug":"k-2","link":"#k-2","children":[]},{"level":2,"title":"b","slug":"b-2","link":"#b-2","children":[]},{"level":2,"title":"y","slug":"y","link":"#y","children":[]},{"level":2,"title":"模型容量","slug":"模型容量","link":"#模型容量","children":[]},{"level":2,"title":"模型参数","slug":"模型参数","link":"#模型参数","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"y = kx + b","slug":"y-kx-b-2","link":"#y-kx-b-2","children":[]},{"level":2,"title":"k","slug":"k-3","link":"#k-3","children":[]},{"level":2,"title":"b","slug":"b-3","link":"#b-3","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI大模型实战高手课/17｜模型解剖：探究模型内部到底是什么？.md","filePath":"AI大模型实战高手课/17｜模型解剖：探究模型内部到底是什么？.md","lastUpdated":1795452664000}'),i={name:"AI大模型实战高手课/17｜模型解剖：探究模型内部到底是什么？.md"};function s(r,e,o,h,p,d){return n(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="_17-模型解剖-探究模型内部到底是什么" tabindex="-1">17 | 模型解剖：探究模型内部到底是什么？ <a class="header-anchor" href="#_17-模型解剖-探究模型内部到底是什么" aria-label="Permalink to &quot;17 | 模型解剖：探究模型内部到底是什么？&quot;">​</a></h1><p>你好，我是独行。</p><p>上节课我们手敲了一个 Transformer 模型，实际最终训练出来的模型，参数量大概在 1.2 亿左右，文件大小约 505M，这一节课我们再来探究一个非常有意思的问题：这个 505M 的文件内部到底存放的是什么？</p><p>前段时间我们本地运行过 ChatGLM3-6B，你还记得吗？6B 的模型文件分为 8 个，有的版本是 5 个，几个文件加在一起大约 20G，6B 的爷爷 130B 模型文件加起来近 240G。不知道你有没有同样的疑问，在我最早接触大语言模型的时候，就非常好奇，大模型文件里到底存的是什么？随着不断地研究学习，总算有了一知半解，这节课就来和你分享一下。</p><h2 id="模型文件" tabindex="-1">模型文件 <a class="header-anchor" href="#模型文件" aria-label="Permalink to &quot;模型文件&quot;">​</a></h2><p>所谓模型文件，也可以叫模型权重，里面大部分空间存放的是模型的参数：权重（Weights）和偏置（Biases），当然也有一些其他信息，比如优化器状态、其他元数据，比如 epoch 数等。我们使用的是 PyTorch 框架，生成的模型权重文件格式是.pth，如果使用 TensorFlow 或者 Hugging Face Transformers 等框架，也有可能是.bin 格式的文件。模型预训练完成后，我们可以调用下面的代码保存模型。</p><ol><li>只保存权重</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>torch.save(model.state_dict(), &#39;model_weights.pth&#39;)</span></span></code></pre></div><ol start="2"><li>保存权重和架构（模型的结构）</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>torch.save(model, model_path)</span></span></code></pre></div><p>一般来说，生产环境不建议把模型的架构也一起保存，因为这个方法保存的模型与 Python 的版本和模型定义的代码紧密相关，如果在不同的环境或 PyTorch 版本中加载，可能会遇到兼容性的问题。而方法一具有更好的兼容性，当你需要迁移到不同的平台或更新项目依赖的时候，这种方式通常会带来更少的问题。</p><h2 id="权重和偏置" tabindex="-1">权重和偏置 <a class="header-anchor" href="#权重和偏置" aria-label="Permalink to &quot;权重和偏置&quot;">​</a></h2><p>权重是神经网络中最重要的参数之一。在前向传播过程中，输入数据会与权重相乘，这是神经网络学习特征和模式的基本方式。权重决定了输入数据如何影响输出结果。</p><p>偏置是添加到加权输入之后的参数，用于调整输出。偏置允许模型输出在没有输入或所有输入都为零的时候调整到某个基线值。</p><h2 id="y-kx-b" tabindex="-1">y = kx + b <a class="header-anchor" href="#y-kx-b" aria-label="Permalink to &quot;y = kx + b&quot;">​</a></h2><h2 id="k" tabindex="-1">k <a class="header-anchor" href="#k" aria-label="Permalink to &quot;k&quot;">​</a></h2><h2 id="b" tabindex="-1">b <a class="header-anchor" href="#b" aria-label="Permalink to &quot;b&quot;">​</a></h2><p>我们可以简单理解，在线性方程</p><ul><li>中， 就是权重， 就是偏置。在神经网络中，</li></ul><h2 id="k-1" tabindex="-1">k <a class="header-anchor" href="#k-1" aria-label="Permalink to &quot;k&quot;">​</a></h2><h2 id="b-1" tabindex="-1">b <a class="header-anchor" href="#b-1" aria-label="Permalink to &quot;b&quot;">​</a></h2><p>权重 决定了每个输入特征对于输出的重要性和影响力。偏置 是一个常数项，它提供除了输入特征之外的额外输入，允许模型输出可以在没有任何输入或所有输入都为零的时候调整到一个基线或阈值。</p><p>根据我们前面学习的神经网络相关的内容，我们知道，在复杂的神经网络中，每个神经元可能都有这样的权重和偏置，用来从前一层接收多个输入信号，对这些信号加权求和后加上偏置，然后通常通过一个非线性激活函数，比如 tanh 和 relu 来生成输出信号，这个输出信号会传递到下一层。每层的权重和偏置都是模型需要学习的参数，它们会根据训练数据进行调整，以最小化模型的预测误差。</p><h2 id="模型可视化" tabindex="-1">模型可视化 <a class="header-anchor" href="#模型可视化" aria-label="Permalink to &quot;模型可视化&quot;">​</a></h2><p>通过一些工具，比如 Netron、TensorBoard、torchviz 等，我们可以窥探一下模型内部的结构。我们先通过 Netron 看一下之前训练好的模型的内部结构。Netron 的使用方法比较简单，下载安装，然后运行软件，出现了这样一个页面：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/1.png" alt=""></a></p><p>我们直接点击 Open Model，加载本地存放的权重文件。之后就出现了模型的结构图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/2.png" alt=""></a></p><p>回想一下上节课构建模型的代码，我们设计这个模型的时候，选择了 6 层 TransformerDecoder-only 架构，通过可视化模型结构，我们可以看到模型内部包含的各个层，比如Embedding、6 个 TransformerDecoderLayer、Linear 等。接下来我们挨个看一下。</p><h3 id="embedding-层" tabindex="-1">Embedding 层 <a class="header-anchor" href="#embedding-层" aria-label="Permalink to &quot;Embedding 层&quot;">​</a></h3><p>点击第一个 Embedding 节点，右边会展示这个节点的详细信息。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/3.png" alt=""></a></p><p>weight(98631*512) 表明这是一个有 98631 行和 512 列的矩阵。在这个矩阵里，每一行对应一个特定的词向量。对一个词汇表中的每一个可能的词或标记，这个矩阵提供了一个 512 维的嵌入向量。在实际处理过程中，这一步不需要乘法计算，只需要一个索引查找操作即可。tensor: float32[98631,512]表明这是一个 FP32 精度的变量，98631 表明训练时使用了 98631个词汇。后面在模型轻量化的部分我会给你介绍精度的概念，这里我就不多说了。</p><h3 id="transformerdecoderlayer" tabindex="-1">TransformerDecoderLayer <a class="header-anchor" href="#transformerdecoderlayer" aria-label="Permalink to &quot;TransformerDecoderLayer&quot;">​</a></h3><p>我们选中其中一个 TransformerDecoderLayer 层，右侧会展示这一层的详细信息，可以看到具体的实现类是 torch.nn.modules.transformer.TransformerDecoderLayer，包含下面这些组件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>torch.nn.modules.activation.MultiheadAttention, torch.nn.modules.activation.Multi</span></span>
<span class="line"><span>torch.nn.modules.linear.Linear,</span></span>
<span class="line"><span>torch.nn.modules.dropout.Dropout,</span></span>
<span class="line"><span>torch.nn.modules.linear.Linear,</span></span>
<span class="line"><span>torch.nn.modules.normalization.LayerNorm,</span></span>
<span class="line"><span>torch.nn.modules.normalization.LayerNorm,</span></span>
<span class="line"><span>torch.nn.modules.normalization.LayerNorm,</span></span>
<span class="line"><span>torch.nn.modules.dropout.Dropout,</span></span>
<span class="line"><span>torch.nn.modules.dropout.Dropout,</span></span>
<span class="line"><span>torch.nn.modules.dropout.Dropout</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/4.png" alt=""></a></p><p>这是模型的整体结构图，我们用另一个工具，查看一下具体的节点图。安装 torchviz，执行下面的代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x = torch.randint(10000, (50,))  # 假设一个序列长度为10的输入</span></span>
<span class="line"><span>y = model(x)</span></span>
<span class="line"><span>dot = make_dot(y.mean(), params=dict(model.named_parameters()), show_attrs=True,</span></span>
<span class="line"><span>dot.render(filename=&quot;net&quot;, format=&#39;png&#39;)</span></span>
<span class="line"><span>生成一张大的 png 图片，当然也支持 pdf 格式，改成 format=&#39;pdf&#39; 就可以。实际测试下</span></span></code></pre></div><p>来，pdf 比 png 清晰度更高，我截取了一部分图片，你可以看一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/5.png" alt=""></a></p><p>这里有整个网络结构的顺序图，具体每个节点的含义，感兴趣的话你可以查询下，比如AccumulateGrad、SplitBackward0、UnsqueezeBackward0 这些，基本都是和计算损失相关的。你要知道，模型的训练过程就是不断调整权重的过程，调整权重的依据就是根据损失函数计算损失，通过反向传播不断调整权重使损失最小，达到理想损失值后，把权重记录下来保存。</p><p>在推理的时候就简单了，数据达到节点（神经元）后，先从输入层到隐藏层，再从隐藏层到输</p><h2 id="y-kx-b-1" tabindex="-1">y = kx + b <a class="header-anchor" href="#y-kx-b-1" aria-label="Permalink to &quot;y = kx + b&quot;">​</a></h2><h2 id="a" tabindex="-1">a = <a class="header-anchor" href="#a" aria-label="Permalink to &quot;a =&quot;">​</a></h2><p>出层。每一层都执行类似</p><ul><li>的公式计算，然后应用激活函数，比如</li></ul><h2 id="relu-y" tabindex="-1">ReLU(y) <a class="header-anchor" href="#relu-y" aria-label="Permalink to &quot;ReLU(y)&quot;">​</a></h2><h2 id="a-1" tabindex="-1">a <a class="header-anchor" href="#a-1" aria-label="Permalink to &quot;a&quot;">​</a></h2><h2 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to &quot;x&quot;">​</a></h2><h2 id="k-2" tabindex="-1">k <a class="header-anchor" href="#k-2" aria-label="Permalink to &quot;k&quot;">​</a></h2><h2 id="b-2" tabindex="-1">b <a class="header-anchor" href="#b-2" aria-label="Permalink to &quot;b&quot;">​</a></h2><ul><li>，最后把 继续传递到下一层，当做，下一层的权重和偏置是已知的，​2​2​2</li></ul><h2 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to &quot;y&quot;">​</a></h2><p>继续计算得出</p><ul><li>。实际应用公式可能会稍微复杂一点，前面第 14 课我们有讲过这方面的内​2</li></ul><p>容，这里就不赘述了。另外，基本都是张量相乘，而不是简单的整数小数相乘。</p><p>模型内部的逻辑基本就是这样，机器学习框架如 PyTorch 可以根据描述文件，将模型重构出来，进行训练和推理。接下来我们再看一下模型的容量。</p><h2 id="模型容量" tabindex="-1">模型容量 <a class="header-anchor" href="#模型容量" aria-label="Permalink to &quot;模型容量&quot;">​</a></h2><p>这节课我们使用的模型大小是 505M，根据上节课模型参数量的计算方式，我们得出参数量N=1.2 亿，模型的精度使用的是 float32。也就是说，每个参数需要 4 字节的存储空间，所以我们大致算一下，纯参数方面需要约 460M 的空间（1.2 亿 *4/1024/1024），其余的 40M 空间可能存放的是模型结构、元数据等等。</p><p>上面我们提到的 Embedding 层，权重是 tensor: float32[98631,512]，表示在 Embedding 层参数量 =98631*512=50491392，存储量大约在 200M，所以这么看来 Embedding 层在存储方面基本就占用了整个模型的 40%，参数方面，5049 万 /1.2 亿也约等于 40%，所以 Embedding层在整个模型中的作用还是非常大的。</p><h2 id="模型参数" tabindex="-1">模型参数 <a class="header-anchor" href="#模型参数" aria-label="Permalink to &quot;模型参数&quot;">​</a></h2><p>基于这些知识，我们再来梳理一下参数的含义，还是以 embedding 层来解释，我们举一个小一点的例子，用 5*10 的矩阵来讲。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E5%AE%9E%E6%88%98%E9%AB%98%E6%89%8B%E8%AF%BE/images/17/6.png" alt=""></a></p><p>这是一个具有 50 个参数的矩阵，每个参数（矩阵中的每个数值）表示词向量在特定维度上的权重或特征。例如，第一行 [0.5, -0.2, 0.3, …, 0.7] 表示第一个词在 10 个不同特征维度上的数值表示。如果我们把 Embedding 层设置为“可训练”，那么在模型训练的过程中会根据损失计算，反向传播后更新某个参数，这样可以让模型更好地表示某个词，来达到训练的目的。在最终推理过程中，词向量会被传播下去，作为下一层的神经网络的输入，参与到后续计算过程中。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课的内容比较有意思，而且很少有人从这个角度去分析。实际上是前面课程内容的一个反向理解，就好比通过 Java 字节码文件反推 Java 编码过程一样。我们来简单梳理下重点。</p><h2 id="y-kx-b-2" tabindex="-1">y = kx + b <a class="header-anchor" href="#y-kx-b-2" aria-label="Permalink to &quot;y = kx + b&quot;">​</a></h2><h2 id="k-3" tabindex="-1">k <a class="header-anchor" href="#k-3" aria-label="Permalink to &quot;k&quot;">​</a></h2><h2 id="b-3" tabindex="-1">b <a class="header-anchor" href="#b-3" aria-label="Permalink to &quot;b&quot;">​</a></h2><ol><li><p>模型里存放的是各个层的权重和偏置，类似于里的 和 。</p></li><li><p>机器学习框架如 PyTorch 可以识别模型文件，并且把模型结构重构出来进行训练和推理。</p></li><li><p>模型训练过程就是不断前向传播、损失计算、反向传播、参数更新的过程。</p></li><li><p>模型推理就是根据训练好的参数，进行前向传播的过程。</p></li><li><p>我们可以使用 Netron、torchviz 等工具可视化模型结构，辅助理解。</p></li></ol><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>刚刚我们提到过，像 6B、130B 这些商用的大模型，权重文件是分开存放的，比如 6B，8 个权重文件，每个大约 2GB，请你思考一下，为什么要这么设计？分开存放的话最终使用的时候是怎么合并的，或者说需不需要合并？这个问题有点难度，欢迎你在评论区留言和我一起讨论，如果你觉得这节课的内容对你有帮助的话，也欢迎分享给其他朋友，我们下节课再见！</p>`,73)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
